/**
 * 上传服务
 * 提供图片和文件上传功能
 */
import { ApiUpload } from '../api-upload';
import { validateFile, photoCompressor, getFileInfo } from './upload-base';
import { FILE_TYPE } from "@/types/upload.ts";
import { UploadResult, ImageDimensions } from "../../types/upload.d";
import { t } from "../../language";
import {showToastFun} from "../../utils/util"

/**
 * 上传图片
 * @param imageFile 图片文件对象
 * @param needCompression 是否需要压缩，默认true
 * @param dimensions 尺寸信息 { width, height }
 * @returns 上传结果
 */
export async function uploadImage(
    imageFile: File, 
    needCompression: boolean = true, 
    dimensions: ImageDimensions | null = null
): Promise<UploadResult> {
    // 验证文件
    if (!validateFile(imageFile, 'IMAGE')) {
        throw new Error(t('invalidImageFile'));
    }

    let fileToUpload = imageFile;

    // 压缩图片
    if (needCompression) {
        try {
            fileToUpload = await photoCompressor(imageFile);
        } catch (error) {
            console.error('Image compression failed:', error);
            fileToUpload = imageFile; // 使用原始图片
        }
    }

    try {
        // 准备上传
        const prepareResponse = await prepareMediaUpload(fileToUpload, dimensions);

        // 检查文件是否已存在
        if (prepareResponse.exists) {
            console.log('Image already exists on server');
            return {
                url: prepareResponse.media_url!,
                mediaId: prepareResponse.media_id!
            };
        }

        // 执行S3上传
        if (prepareResponse.presigned_url) {
            await executeS3Upload(fileToUpload, prepareResponse.presigned_url);

            // 确认上传完成
            const confirmResponse = await confirmMediaUpload(prepareResponse.upload_id!);

            return {
                url: confirmResponse.media_url,
                mediaId: confirmResponse.media_id
            };
        } else {
            throw new Error('No presigned URL provided');
        }
    } catch (error) {
        console.error('Image upload failed:', error);
        showToastFun(t('imageUploadFailed'));
        throw error;
    }
}

/**
 * 上传文档
 * @param documentFile 文档文件对象
 * @returns 上传结果
 */
export async function uploadDocument(documentFile: File): Promise<UploadResult> {
    // 验证文件
    if (!validateFile(documentFile, 'DOCUMENT')) {
        throw new Error(t('invalidDocumentFile'));
    }

    try {
        // 准备上传
        const prepareResponse = await prepareMediaUpload(documentFile);

        // 检查文件是否已存在
        if (prepareResponse.exists) {
            console.log('Document already exists on server');
            return {
                url: prepareResponse.media_url!,
                mediaId: prepareResponse.media_id!
            };
        }

        // 执行S3上传
        if (prepareResponse.presigned_url) {
            await executeS3Upload(documentFile, prepareResponse.presigned_url);

            // 确认上传完成
            const confirmResponse = await confirmMediaUpload(prepareResponse.upload_id!);
            return {
                url: confirmResponse.media_url,
                mediaId: confirmResponse.media_id
            };
        } else {
            throw new Error('No presigned URL provided');
        }
    } catch (error) {
        console.error('Document upload failed:', error);
        showToastFun(t('documentUploadFailed'));
        throw error;
    }
}

/**
 * 准备媒体上传
 * @param file 文件对象
 * @param dimensions 尺寸信息 { width, height }
 * @returns 上传准备响应
 */
async function prepareMediaUpload(file: File, dimensions: ImageDimensions | null = null): Promise<any> {
    try {
        // 获取文件信息
        const fileInfo = await getFileInfo(file);
        if (!fileInfo) {
            throw new Error('Failed to get file information');
        }

        // 确定文件类型
        const isImage = file.type.startsWith('image/');
        const fileType = isImage ? FILE_TYPE.IMAGE : FILE_TYPE.DOCUMENT;

        // 准备请求参数
        const params: any = {
            md5_hash: fileInfo.digest,
            file_ext: file.name.split('.').pop()?.toLowerCase() || '',
            file_size: file.size,
            content_type: file.type,
            file_type: fileType
        };

        // 如果是图片且提供了尺寸信息
        if (isImage && dimensions) {
            params.width = dimensions.width;
            params.height = dimensions.height;
        }

        // 调用新的API封装
        const response = await ApiUpload.prepareMediaUpload(params);
        return response.data;
    } catch (error) {
        console.error('Prepare media upload failed:', error);
        throw error;
    }
}

/**
 * 执行S3上传
 * @param file 上传文件
 * @param presignedUrl 预签名URL
 * @returns 是否上传成功
 */
export async function executeS3Upload(file: File, presignedUrl: string): Promise<boolean> {
    try {
        const uploadResponse = await fetch(presignedUrl, {
            method: 'PUT',
            body: file,
            headers: {
                'Content-Type': file.type
            }
        });

        if (uploadResponse && uploadResponse.status === 200) {
            return true;
        }

        throw new Error(uploadResponse ?
            `Upload response ${uploadResponse.statusText}` :
            'Empty response'
        );
    } catch (error) {
        console.error('S3 upload failed:', error);
        throw error;
    }
}

/**
 * 确认媒体上传完成
 * @param uploadId 上传ID
 * @returns 确认响应
 */
export async function confirmMediaUpload(uploadId: number): Promise<any> {
    try {
        // 调用新的API封装
        const response = await ApiUpload.confirmMediaUpload(uploadId);
        return response.data;
    } catch (error) {
        console.error('Confirm media upload failed:', error);
        throw error;
    }
} 

