/**
 * 文件处理相关工具函数
 */
import { ALLOWED_FILE_TYPES, FILE_SIZE_LIMITS } from '@/types/upload.ts';
import SparkMD5 from 'spark-md5';
import '@/utils/third-party/compressor.min.js';
import { numberFixed, showToastFun } from "../../utils/util";
import { FileInfo, FileTypeCategory } from "../../types/upload.d";
import { t } from "../../language";

/**
 * 将DataURL转换为File对象
 * @param dataURL 数据URL
 * @param filename 文件名
 * @returns File对象
 */
export function dataURLToFile(dataURL: string, filename: string): File {
    const arr = dataURL.split(',');
    const mime = arr[0].match(/:(.*?);/)![1];
    const bstr = atob(arr[1]);
    let n = bstr.length;
    const u8arr = new Uint8Array(n);
    while(n--) {
        u8arr[n] = bstr.charCodeAt(n);
    }
    return new File([u8arr], filename, { type: mime });
}

/**
 * 将Blob URL转换为File对象
 * @param blobUrl Blob URL
 * @param filename 文件名
 * @returns File对象
 */
export async function blobToFile(blobUrl: string, filename: string): Promise<File> {
    const response = await fetch(blobUrl);
    const blob = await response.blob();
    return new File([blob], filename, { type: blob.type });
}

/**
 * 图片压缩函数
 * @param photoFile 图片文件或数据URL
 * @param quality 压缩质量(可选)
 * @returns 压缩后的文件
 */
export function photoCompressor(photoFile: File | string, quality?: number): Promise<File> {
    return new Promise(async (resolve, reject) => {
        let sizeMB: number;
        let qualityVal: number;
        let upFile: File;

        // 处理不同类型的输入
        if (typeof photoFile === 'string') {
            if (photoFile.startsWith('data:image')) {
                upFile = dataURLToFile(photoFile, new Date().getTime().toString());
            } else if (photoFile.startsWith('blob:http')) {
                upFile = await blobToFile(photoFile, new Date().getTime().toString());
            } else {
                reject(new Error('Invalid file input'));
                return;
            }
        } else {
            upFile = photoFile;
        }

        sizeMB = numberFixed(upFile.size / 1024 / 1024, 1);

        if (typeof quality === "undefined") {
            qualityVal = 0.4;
            if (sizeMB <= 0.2) {
                qualityVal = 0.8;
            } else if (sizeMB <= 0.5) {
                qualityVal = 0.8;
            } else if (sizeMB <= 1) {
                qualityVal = 0.7;
            } else if (sizeMB <= 2) {
                qualityVal = 0.5;
            }
        } else {
            qualityVal = quality;
        }

        // 使用全局Compressor对象
        const Compressor = window.Compressor;
        if (!Compressor) {
            reject(new Error('Compressor not available'));
            return;
        }

        new Compressor(upFile, {
            quality: qualityVal,
            success(result: File) {
                console.log('----> photoCompressor ori_size ' + sizeMB + ', q = ' + qualityVal, result);
                resolve(result);
            },
            fail(res: any) {
                console.log('----> photoCompressor ori_size fail ' + res);
                reject(new Error('Compression failed'));
            },
            error(err: Error) {
                console.error('----> photoCompressor error', err.message);
                reject(err);
            },
        });
    });
}

/**
 * 检查文件类型是否允许上传
 * @param file 文件对象
 * @param allowedTypes 允许的文件类型数组
 * @returns 是否允许上传
 */
 function checkFileType(file: File, allowedTypes: readonly string[]): boolean {
    return allowedTypes.includes(file.type);
}

/**
 * 检查文件大小是否超过限制
 * @param file 文件对象
 * @param sizeLimit 大小限制(字节)
 * @returns 是否在限制范围内
 */
function checkFileSize(file: File, sizeLimit: number): boolean {
    return file.size <= sizeLimit;
}

/**
 * 验证上传的文件
 * @param file 文件对象
 * @param fileType 文件类型('IMAGE'|'DOCUMENT')
 * @returns 是否验证通过
 */
export function validateFile(file: File, fileType: FileTypeCategory): boolean {
    // 检查文件类型
    if (!checkFileType(file, ALLOWED_FILE_TYPES[fileType])) {
        showToastFun(t('fileTypeNotAllowed'))
        return false;
    }

    // 检查文件大小
    if (!checkFileSize(file, FILE_SIZE_LIMITS[fileType])) {
        const sizeMB = FILE_SIZE_LIMITS[fileType] / 1024 / 1024;
        showToastFun(t('fileSizeExceedsLimit', { size: sizeMB }))
        return false;
    }

    return true;
}

/**
 * 计算文件的MD5值
 * @param file 文件对象
 * @returns MD5值
 */
function calculateFileMD5(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
        const spark = new SparkMD5.ArrayBuffer();
        const fileReader = new FileReader();
        const chunkSize = 2097152; // 2MB per chunk
        const chunks = Math.ceil(file.size / chunkSize);
        let currentChunk = 0;

        // 加载下一个数据块
        const loadNext = () => {
            const start = currentChunk * chunkSize;
            const end = Math.min(start + chunkSize, file.size);
            const chunk = file.slice(start, end);
            fileReader.readAsArrayBuffer(chunk);
        };

        fileReader.onload = function(e: ProgressEvent<FileReader>) {
            if (!e.target?.result) {
                reject(new Error('Failed to read file chunk'));
                return;
            }

            // 将当前块添加到spark实例中
            spark.append(e.target.result as ArrayBuffer);
            currentChunk++;

            if (currentChunk < chunks) {
                // 继续读取下一块
                loadNext();
            } else {
                // 所有块都已读取完毕，计算最终的MD5
                const hash = spark.end();
                resolve(hash);
            }
        };

        fileReader.onerror = function(error) {
            reject(new Error('Failed to read file: ' + error));
        };

        // 开始读取第一个块
        loadNext();
    });
}

/**
 * 获取文件信息(包括MD5)
 * @param file 文件对象
 * @returns 文件信息
 */
export async function getFileInfo(file: File): Promise<FileInfo | null> {
    try {
        const digest = await calculateFileMD5(file);
        return {
            name: file.name,
            size: file.size,
            type: file.type,
            digest: digest
        };
    } catch (error) {
        console.error('Failed to get file info:', error);
        return null;
    }
} 