/**
 * 上传相关API服务
 * 提供文件上传的所有功能
 */
import { ApiClient } from './client-api';
import { ApiResponse } from './definitions';
import { 
    MediaUploadResponseInfo, 
    MediaUploadConfirmResponseInfo,
    MediaUploadParams
} from '../models/upload-models';
import {
    API_UPLOAD_PREPARE,
    API_UPLOAD_CONFIRM
} from './api-url';

/**
 * 上传API服务类
 * 提供媒体文件上传准备、确认等功能
 */
export class ApiUpload {
    /**
     * 准备媒体上传
     * @param params 上传参数
     * @returns 上传准备响应
     */
    static async prepareMediaUpload(params: MediaUploadParams): Promise<ApiResponse<MediaUploadResponseInfo>> {
        return await ApiClient.post(
            API_UPLOAD_PREPARE,
            params,
            MediaUploadResponseInfo
        );
    }

    /**
     * 确认媒体上传完成
     * @param uploadId 上传记录ID
     * @returns 确认响应
     */
    static async confirmMediaUpload(uploadId: number): Promise<ApiResponse<MediaUploadConfirmResponseInfo>> {
        return await ApiClient.post(
            API_UPLOAD_CONFIRM,
            { upload_id: uploadId },
            MediaUploadConfirmResponseInfo
        );
    }
} 