/**
 * 上传相关数据模型
 * 定义文件上传相关的所有数据结构
 */
import { BaseResponseData } from './base-models';

/**
 * 媒体上传响应信息
 * 包含上传准备的响应数据
 */
export class MediaUploadResponseInfo extends BaseResponseData {
    /** 文件是否已存在 */
    exists: boolean = false;
    /** 媒体文件ID（exists=true时返回） */
    media_id: number | null = null;
    /** 媒体访问URL（exists=true时返回） */
    media_url: string | null = null;
    /** 上传记录ID（exists=false时返回） */
    upload_id: number | null = null;
    /** 预签名上传URL（exists=false时返回） */
    presigned_url: string | null = null;
}

/**
 * 媒体上传确认响应信息
 * 包含上传确认的响应数据
 */
export class MediaUploadConfirmResponseInfo extends BaseResponseData {
    /** 媒体文件ID */
    media_id: number = 0;
    /** 媒体访问URL */
    media_url: string = '';
}

/**
 * 媒体上传请求参数
 * 用于准备媒体上传的参数（7个参数：md5_hash, file_ext, file_size, content_type, file_type, width, height）
 */
export interface MediaUploadParams {
    /** 文件MD5哈希值 */
    md5_hash: string;
    /** 文件扩展名 */
    file_ext: string;
    /** 文件大小（字节） */
    file_size: number;
    /** MIME类型 */
    content_type: string;
    /** 文件类型 */
    file_type: number;
    /** 图片/视频宽度 */
    width?: number | null;
    /** 图片/视频高度 */
    height?: number | null;
} 